def rotation_offset(a, b):
    n = len(a)
    if n != len(b):
        return -1
    if n == 0:
        return 0
    for k in range(n):
        if a[k:] + a[:k] == b:
            return k
    return -1

def lexicographically_smallest_rotation(lst):
    n = len(lst)
    if n == 0:
        return []
    best = lst[:]
    for k in range(1, n):
        rot = lst[k:] + lst[:k]
        if rot < best:
            best = rot
    return best

def are_all_rotations_equal(lst):
